/**
 * Skill Template Workflow Modules
 *
 * This file is generated by splitting the legacy monolithic
 * templates file into workflow-focused modules.
 */
import type { SkillTemplate, CommandTemplate } from '../types.js';

export function getOnboardSkillTemplate(): SkillTemplate {
  return {
    name: 'orbit-onboard',
    description: 'Single-pass onboarding reference for orbit - orientation to the self-contained tool, the canonical workflow, and the full command table. No demo changes, no interactive walkthrough. Use when someone is new to orbit or asks how its workflow fits together.',
    instructions: getOnboardInstructions(),
    license: 'MIT',
    compatibility: 'Requires orbit CLI.',
    metadata: { author: 'openspec', version: '1.0' },
  };
}

function getOnboardInstructions(): string {
  return `
> **Note on \`/orbit:onboard\` emit semantics**: this command does NOT emit a run-summary JSON (\`orbit-run-summary-emit\`'s \`Emit scope\` lists \`/orbit:onboard\` as a non-emit command): it is a single-pass reference read that advances no workflow state and produces no artifact in the user's project. Later edits MUST keep it non-emitting.

This skill is the single source of the \`/orbit:onboard\` onboarding read; the command is a thin launcher that invokes it. Single-pass: render Sections 1-5 in order.

---

## Section 1: Orientation

You're reading this because orbit is installed and you ran \`/orbit:onboard\`. There's nothing to verify and nothing to "overlay": orbit-spec is a **self-contained** spec-driven workflow tool — a hard fork of openspec@1.3.1 with orbit's editorial layer built into the \`orbit\` CLI itself.

Quick orientation:

- **CLI**: \`orbit\`. Run \`orbit --version\` to confirm it's on your PATH; it prints orbit's own version. Separately, the engine is pinned at the upstream baseline 1.3.1.
- **Workspace**: \`orbit/\` holds your specs (\`orbit/specs/\`) and in-flight changes (\`orbit/changes/\`). If \`orbit/\` doesn't exist yet, run \`orbit init\` first.
- **Surface**: the \`/orbit:*\` slash commands and their skills are generated by \`orbit init\` — this onboarding read is one of them.

No install verification needed. On to what orbit is and how its workflow flows.

---

## Section 2: Identity statement

Orbit (orbit-spec) is a spec-driven workflow tool — a **self-contained hard fork** of \`@fission-ai/openspec@1.3.1\`. The upstream engine and orbit's editorial/judgment layer live together in one tool, invoked as \`orbit\`; there is no overlay and no separately-installed CLI. The engine is pinned at 1.3.1 (deliberate, surgical upgrades only). Orbit shares concepts with upstream OpenSpec but ships an opinionated workflow with distinct disciplines, not a delta on top of upstream's defaults.

What makes orbit distinctive vs running upstream alone:

- **Editorial review** — \`/orbit:review\` runs a 9-pass editorial pass over the artifacts (proposal mode), a 7-pass pass over the post-apply product state (system mode, which wraps upstream's \`verify-change\` as Pass 0), or a 6-pass gate-less pass over an architecture doc (architecture mode). Its REVIEWER axis says who runs the pass — a different AI (codex / fresh Claude / GPT) for a second opinion, or a blind pair of two independent passes; the review skill states its values and shorthands. Record vocabulary is frozen across the merge: the packaging emit stays \`command: "review-external"\`, findings stay \`external-<as>-<TS>.md\`. \`/orbit:address-reviews\` walks each finding, inline \`@review:\` marker or external-review findings file, one by one through pushback → classify → fix → ripple-cascade → remove, ripple edits applying by default to IN-set files (everything outside the four lifecycle-invariant OUT categories; \`--no-cascade\` opts out).

- **Drift audit** — \`/orbit:audit-drift\` scans for drift between captured knowledge (specs, lenses, governing docs) and reality across four categories: vocabulary residue (FROM names of renamed requirements still appearing), lens staleness (perspectives or critical-paths referencing nonexistent capabilities), cross-doc consistency (CLAUDE.md / project.md disagreement with current specs), archive coherence (ADDED requirements missing from baseline, RENAMED FROM names lingering). Standalone for "something feels off" checks; auto-invoked as system-mode review Pass 6 and as a pre-archive sweep.

- **Capture (lenses)** — \`orbit/lenses/perspectives.md\` records named callers worth simulating from during review; \`orbit/lenses/critical-paths.md\` records flows worth walking end-to-end. Lenses grow organically through \`/orbit:explore\` capture triggers; system-mode review Passes 4-5 consult them.

- **Program architecture** — \`/orbit:architect\` and \`orbit architecture status\`: the cross-change declaration tier above per-change flow. Architecture docs under \`orbit/architecture/\` declare program stages via parseable heading conventions (\`### Stage <id> — <title>\` + optional \`Depends-on:\`/\`Complete:\` slots); stage state is COMPUTED from disk (which changes/explores cite the stage via \`architecture: {doc, stage}\` metadata), never stored. \`/orbit:review --as architecture\` reviews a doc (6 passes, no gate). Never a required entry point — \`/orbit:explore\` plus hand-editing remains first-class.

- **JSON run-summary emission via the engine emit surface** — every editorial and lifecycle command persists a JSON run summary at completion (per chunk for \`/orbit:apply\`) through \`orbit emit <command> --change <name> --payload <file>\`: the AI supplies only the narrative payload and the required nullable \`model\`; the engine owns the spine, the facts and computed extensions (explore counts, apply's task arithmetic, \`files_touched\`), \`next_recommended\`, the filename, and a strict write gate that refuses an invalid emit with NO file. Summaries land in one of FOUR places: \`orbit/changes/<name>/.orbit-runs/\` (per change), \`orbit/explore/<name>/.orbit-runs/\` (named explorations), \`orbit/architecture/.orbit-runs/\` (architect sessions and architecture reviews, shared by all docs, never moved by archiving) and \`orbit/.orbit-runs/\` (project-wide), each a universal spine with per-command extensions. (\`/orbit:onboard\` is one of the few commands that does NOT emit: it is a reference read.)

- **Cold-start orientation** — \`orbit status\` (bare: the current sprint; \`--full\`: the whole program) and \`orbit status --change <name> --boot\`: artifact pointers in read order, the latest emit per command family with its headline, explore-history presence, and the **Touchpoints** view — predicted from design.md's \`## Touchpoints\` before apply commits exist, the diff-computed ACTUAL file map once they do. Boot is READ-ONLY and computed fresh: no hand-maintained handoff files.

- **Execution disciplines** codified in \`orbit-conventions\`:
  - **Read-before-reference** (authoring-time): read a construct's actual definition before naming it in code, specs or docs; never infer its shape from common patterns.
  - **Change completeness** (modification-time): a modification to a change in flight applies across ALL affected artifacts before it is called done; no known residue is left for a review to catch.
  - **Pushback** (review-time): verify each flagged issue against current state before acting; stale findings are reported with evidence and suppressed.
  - **No-chaining** (turn boundary): the AI invokes only the orbit commands the user's message explicitly requests, recommending, never invoking, the next unless the project's \`chain\` setting grants it; a completed command ends the turn at the position readout and \`Ready when you are:\` — gate \`passed\` means *eligible*, not *commanded*.
  - **Decision-writing** (call-time): while a setting reads them (\`orbit decisions status\`), the AI records each stop, its resolution and each call in a ledger area (\`orbit emit stop\`, \`orbit emit resolution\`, \`orbit emit ledger\`) without changing what the user sees or is asked; an answer or fix to a record already in the trail is written whatever the setting, and a designed prompt is a seam, not a stop.

---

## Section 3: Canonical-flow walkthrough

Orbit's canonical flow is architect-first and returns to architect: an architect session plans the work, the 9 per-change phases run once per change (a stage may be served by several changes), and a closing architect session ratifies the stage and takes up the next. Each phase maps to a \`/orbit:*\` slash command. The flow is:

\`\`\`
   architect ─→ ┌─ per change ──────────────────────────────────────────────────┐
                │ explore ─→ propose ─→ review ─→ address-reviews ─→ apply ─→   │
                │ verify ─→ review --as system ─→ address-reviews ─→ archive    │
                └───────────────────────────────────────────────────────────────┘ ─→ architect (ratify the stage)
\`\`\`

**Architect (\`/orbit:architect <name>\`)**: Where new work starts, and where it returns. The session authors or resumes a program architecture doc under \`orbit/architecture/\`: its stages, its rulings, and the engine-rendered state of each stage. After a stage's changes archive, the closing session reviews the stage, ratifies it when its exits hold, and takes up the next. An architect session is never required: nothing refuses, gates or flags work that skipped one, and \`/orbit:explore\` remains the path for a one-off fix.

**Phase 1 — explore (\`/orbit:explore [<name>]\`)**: Thinking through one change, after architect, with orbit as thinking partner on an idea, problem or comparison. Named mode (\`/orbit:explore <name>\`) auto-captures decisions to \`orbit/explore/<name>/explore.md\`'s six sections (Premise / Mechanism / Decisions / Open questions / Considered & out / References); bare mode stays in conversation until 2+ substantive decisions emerge, then prompts for a name. Capture triggers also offer to save **lenses**: \`perspectives.md\` records named callers worth validating from during review (e.g., "API client"), \`critical-paths.md\` flows worth walking end-to-end (e.g., "First-time user adds their first device"); system-mode review Passes 4-5 consult them.

**Phase 2 — propose (\`/orbit:propose <name>\`)**: Generates the change artifacts (proposal, design, specs, tasks) from \`explore.md\` (consume mode) or from a prompted description (standalone mode). Consume mode treats \`explore.md\` as authoritative: Premise → proposal motivation; Decisions → spec deltas, design and tasks; Considered & out → design's "Alternatives considered"; References → contextual reads. Each Open question is resolved now (a Decision), deferred (an \`@review:\` marker) or abandoned (to Considered & out). The staging directory then moves to \`orbit/changes/<name>/\`, \`explore.md\` with it, and the run summary goes to \`orbit/changes/<name>/.orbit-runs/propose-<TS>.json\`.

*The PR layer.* When \`pr:\` in \`orbit/config.yaml\` names an active regime, propose is also where the change's **draft PR** opens, so CI runs from day one. The key takes three values: \`never\` (the default, and what an absent key means: no PR machinery anywhere), \`per-proposal\` (each change gets its own \`<change-name>\` branch and PR) and \`per-architecture\` (a change CITING an architecture doc rides that doc's program branch under one program PR; a change with NO citation falls back to per-proposal). The citation selects the target; the config only selects the regime. With no git remote or no \`gh\` CLI an active mode degrades to \`never\` behavior for that invocation and says so in one line — the lifecycle never blocks on the PR layer. READY is orbit's terminus: the archive phase flips the PR ready, and merging it is the user's act.

**Phase 3 — review (proposal mode, \`/orbit:review <name> --as proposal\`)**: The editorial pre-apply pass over the artifacts — 9 passes, from structure and delta integrity through gap hunt to a pre-handoff sweep, scored on Completeness / Correctness / Coherence with CRITICAL / WARNING / SUGGESTION severities. The run summary persists FIRST (\`orbit emit review\`); the report is then \`orbit status --change <name> --report\`'s ENGINE-RENDERED output pasted verbatim, its gate line, position and eligibility computed from the gate graph, so the AI never authors a verdict.

**Phase 4 — address-reviews (\`/orbit:address-reviews <name>\` or \`--from-file <path>\`)**: Walks each finding (or \`@review:\` marker), one by one, through pushback → classify → fix → ripple-cascade → remove-marker. The classification IS the lane: stale findings are suppressed with evidence; obvious fixes are previewed at triage, then applied without prompts; a decision gets a full-prose briefing ratified in chat (a closure prompt is optional and never precedes the briefing); an unresolvable finding is filed as a task or becomes \`@todo:\` / \`@review(escalated):\`. Ripple edits to IN-set files apply by default (\`--no-cascade\` opts out). **Cross-AI loop**: \`/orbit:review\`'s reviewer axis reaches a different AI for a second opinion (the review skill states how the prompt reaches it and how its return is saved); the change-scoped walk discovers the saved return, and \`--from-file\` aims at it explicitly (the external handoff is in the review skill's \`references/external-handoff.md\`).

**Phase 5 — apply (\`/orbit:apply <name>\`)**: Implements \`tasks.md\` chunk by chunk; at each chunk's end \`orbit emit apply\` writes \`.orbit-runs/apply-<TS>.json\`, its chunk identity, task arithmetic, \`files_touched\` and next recommendation engine-computed from the AI's narrative payload. The user can interrupt between chunks. A task that surfaces a premise problem (a design issue, say) pauses apply for direction: \`@review(escalated):\` markers, artifact updates or scope cuts.

**Phase 6 — verify (\`/orbit:verify <name>\`)**: Runs upstream's \`orbit-verify-change\` skill — structural correctness check confirming tasks are complete, spec coverage holds, and design adherence is intact. orbit composes this as the structural gate before system-mode review.

**Phase 7 — review (system mode, \`/orbit:review <name> --as system\`)**: Post-apply review of the whole product state. Pass 0 wraps \`orbit-verify-change\`. Passes 1-6: Baseline Compliance (does the change break \`orbit/specs/\` requirements?) / Cohesion (callers and dependents outside the tasks: signature drift, ripples) / Surface Walk (is every CLI/MCP/HTTP/public-function surface in \`orbit/specs/\` still coherent?) / Perspective Reviews (each caller in \`orbit/lenses/perspectives.md\`, simulated) / Critical-Path Scan (each flow in \`orbit/lenses/critical-paths.md\`, walked end-to-end) / Drift / Residue (\`/orbit:audit-drift\` as a library). Run summary: \`.orbit-runs/review-system-<TS>.json\`.

**Phase 8 — address-reviews (system-mode findings)**: Same \`/orbit:address-reviews\` lifecycle as Phase 4, applied to system-mode review's findings. The cross-AI external loop also works here (\`/orbit:review <name> --as system --reviewer external\`).

**Phase 9 — archive (\`/orbit:archive <name>\`)**: Moves the change to \`orbit/changes/archive/<YYYY-MM-DD>-<name>/\` and runs sync-specs (\`orbit-sync-specs\`) to merge its spec deltas (ADDED/MODIFIED/REMOVED/RENAMED) into the baseline at \`orbit/specs/\`. Pre-archive sweeps: unresolved \`@review:\` markers (address, or convert to \`@todo:\`) and audit-drift (\`/orbit:audit-drift --context pre-archive\`). \`.orbit-runs/\` travels with the change, keeping the whole audit trail, and the run summary lands at \`.orbit-runs/archive-<TS>.json\` inside the archive.

*The PR layer.* For a PR-attached change, archive continues past the emit as one designed **tail**: commit the archive's own writes, push, then — for a per-change PR, rewrite the description into an achievement landmark and flip the PR **READY**; for a PROGRAM PR (a change citing an architecture doc under \`pr: per-architecture\`), APPEND this stage's entry to the program PR's body and flip NOTHING — stage archives never flip the program PR; its READY flip is the human's act at arc-done, which \`/orbit:architect\`'s readout surfaces beside the merge. **MERGING IS THE USER'S ACT**: no orbit workflow or engine path invokes \`gh pr merge\`. The tail degrades gracefully at every step (no remote, no \`gh\`, a rejected push) with a one-line note of what completed and what was skipped; the archive itself never rolls back.

---

## Section 4: Quick-reference command table

The \`/orbit:*\` command surface — 14 commands. Every row is generated into your project by \`orbit init\`. One-line descriptions follow.

| Command | One-line description |
|---------|---------------------|
| \`/orbit:address-reviews [<scope>] [--from-file <path>] [--no-cascade]\` | Walk inline \`@review:\` markers or \`--from-file\` findings (external-review markdown, internal review JSON or audit-drift JSON, detected by content) finding by finding through pushback → classify → fix → ripple-cascade → remove, ripple edits applying to IN-set files by default (\`--no-cascade\` opts out). Aimed at a change, it walks the change's markers, every outstanding pass its reviewed gates report (external returns included) and its unwalked audit-drift emits, one log per source. Decision-lane findings get prose briefings ratified in chat. |
| \`/orbit:apply <name>\` | Implement tasks from \`tasks.md\` chunk-by-chunk with end-of-chunk run-summary emits. Pauses on premise problems. |
| \`/orbit:architect [<doc-name>]\` | Author or resume an architecture doc (program layer): parseable stage declarations, ruling capture, engine-rendered state, completion-ratification flow. Never a required entry point. |
| \`/orbit:archive <name>\` | Move change to \`orbit/changes/archive/\`, run sync-specs to propagate deltas to baseline. Pre-archive \`@review:\` marker check + audit-drift sweep. |
| \`/orbit:audit-drift [<change-name>]\` | Scan for drift between captured knowledge and reality (4 categories: vocabulary, lens, cross-doc, archive). Standalone or library-call. |
| \`/orbit:continue <name>\` | Create the next artifact in the change's workflow. |
| \`/orbit:explore [<name>]\` | Thinking through a change, after architect. Named: auto-captures decisions to \`explore.md\`. Bare: stays in chat until crystallization. |
| \`/orbit:ff\` | Fast-forward through artifact creation in one go. |
| \`/orbit:new <name>\` | Start a new change using the experimental artifact workflow. |
| \`/orbit:onboard\` | Run this skill (the reference walkthrough you're reading now). |
| \`/orbit:propose <name>\` | Generate proposal + design + specs + tasks artifacts in one step. Consume mode reads \`orbit/explore/<name>/explore.md\` if present. |
| \`/orbit:review <name> [--as proposal\\|system\\|architecture] [--reviewer <value>]\` | Editorial review: 9 passes proposal-mode (pre-apply), 7 passes system-mode (post-apply, wraps \`verify-change\` as Pass 0), or 6 passes architecture-mode (a doc, no gate). \`--reviewer\` picks who runs the pass — the review skill lists its values and shorthands. |
| \`/orbit:sync <name>\` | Sync delta specs from a change to main specs without archiving. |
| \`/orbit:verify <name>\` | Run upstream's structural verify-change (tasks done, spec coverage, design adherence). Composed as Pass 0 of system-mode review. |

This table documents the user-invocable command surface.

---

## Section 5: Try-it nudge

Two paths from here, depending on what you have:

- **If you have a concrete project idea** — run \`/orbit:architect <name>\`. Replace \`<name>\` with a kebab-case name for the work (e.g., \`add-user-auth\`, \`migrate-postgres-to-sqlite\`, \`redesign-archive-flow\`). The architect session plans it as a program of stages; each stage then runs the per-change flow, starting with \`/orbit:explore <change-name>\` and \`/orbit:propose <change-name>\`. For a one-off fix too small to plan, \`/orbit:explore <change-name>\` alone is a working path.

- **If you're orienting and don't have a concrete idea yet** — run \`/orbit:explore\` (no name). Bare-mode explore stays in thinking-mode without committing to a change. Orbit acts as thinking partner; if 2+ substantive decisions emerge during the conversation, orbit prompts you to crystallize a name. Useful for investigating a vague concern, comparing approaches, or just orienting yourself to the codebase.

When you've gathered findings worth acting on, see \`/orbit:address-reviews\` to walk them. When you want a project-wide drift check, see \`/orbit:audit-drift\`. When you want a cross-AI second opinion, see \`/orbit:review --as <mode> --reviewer external\`.`;
}

export function getOrbitOnboardCommandTemplate(): CommandTemplate {
  return {
    name: 'ORBIT: Onboard',
    description: 'Single-pass onboarding reference - orient to orbit, its canonical workflow, and the command surface',
    category: 'Workflow',
    tags: ['workflow', 'onboarding', 'reference', 'learning'],
    content: `Single-pass onboarding reference for orbit.

This command is a thin launcher: invoke the \`orbit-onboard\` skill (e.g., \`/orbit:onboard\`). The skill carries the complete onboarding body. Do not improvise the walkthrough from this file; load the skill.`,
  };
}
